"""Original native vector VFX and demo souvenir graphics. No stock logos/prices."""
from pathlib import Path
import math,struct,wave
ROOT=Path(__file__).resolve().parents[1]/'public'/'assets'
def save(name,w,h,body,title):
 p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}" role="img"><title>{title}</title>{body}</svg>',encoding='utf-8')
save('effects/black-hole.svg',320,240,'<defs><radialGradient id="halo"><stop stop-color="#0a0914"/><stop offset=".37" stop-color="#21122e" stop-opacity=".94"/><stop offset=".48" stop-color="#b779df" stop-opacity=".4"/><stop offset=".7" stop-color="#6753c4" stop-opacity=".15"/><stop offset="1" stop-color="#4940a0" stop-opacity="0"/></radialGradient><linearGradient id="disk"><stop stop-color="#a985db"/><stop offset=".45" stop-color="#fff0ba"/><stop offset="1" stop-color="#e9a86f"/></linearGradient></defs><ellipse cx="160" cy="120" rx="154" ry="113" fill="url(#halo)"/><g transform="translate(160 120) rotate(-18)" fill="none" stroke="url(#disk)"><ellipse rx="125" ry="34" stroke-width="4" opacity=".3"/><ellipse rx="112" ry="28" stroke-width="2" opacity=".8"/><ellipse rx="100" ry="21" stroke-width="6" opacity=".8"/><circle r="49" stroke-width="3"/><path d="M-50 0a50 50 0 0 1 100 0" stroke-width="7"/></g><circle cx="160" cy="120" r="45" fill="#03050d"/><circle cx="160" cy="120" r="46" fill="none" stroke="#eec9a4" stroke-width="1.2" opacity=".85"/>','Black hole accretion disk — transparent effect graphic')
save('effects/reward-coin.svg',128,128,'<defs><radialGradient id="g"><stop stop-color="#ffebaf"/><stop offset="1" stop-color="#d19c4e"/></radialGradient></defs><circle cx="64" cy="64" r="52" fill="#d39d50" opacity=".12"/><circle cx="64" cy="64" r="38" fill="url(#g)" stroke="#a27742" stroke-width="3"/><circle cx="64" cy="64" r="29" fill="none" stroke="#ffedb6" stroke-width="2"/><path d="M52 45h24M52 45v38h24M52 64h18" fill="none" stroke="#8a642d" stroke-width="5" stroke-linecap="round"/><path d="m105 18 3 9 9 3-9 3-3 9-3-9-9-3 9-3ZM21 85l2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="#e9bb66"/>','Original demo credit coin — no monetary value')
save('effects/empty-reveal.svg',128,128,'<g fill="none" stroke="#87bbc6" stroke-width="2"><circle cx="57" cy="65" r="32" opacity=".65"/><path d="M33 48a24 24 0 0 1 13-8" stroke-linecap="round"/><circle cx="100" cy="28" r="10" opacity=".6"/><circle cx="26" cy="104" r="7" opacity=".5"/><path d="M83 87q12-4 16-14" stroke-dasharray="3 5"/></g>','Empty reward — a few harmless bubbles')
save('effects/bubble-burst.svg',192,192,'<g fill="none" stroke="#c5eef2"><circle cx="96" cy="96" r="45" stroke-width="2" opacity=".8"/><circle cx="96" cy="96" r="61" stroke-width="1" opacity=".3"/><circle cx="33" cy="50" r="7"/><circle cx="149" cy="37" r="10"/><circle cx="164" cy="110" r="6"/><circle cx="48" cy="150" r="11"/><path d="m96 11-2 17m-76 71 16-2m122 60-12-12m-9-121-6 11" stroke-width="3" stroke-linecap="round"/></g>','Cartoon creature burst — no gore')
for symbol,ink in [('NVDA','#b5d99b'),('AAPL','#dce3eb'),('MSFT','#a9cfe3')]:
 save(f'rewards/{symbol.lower()}-demo.svg',240,160,f'<rect x="5" y="5" width="230" height="150" rx="14" fill="#152b3a" stroke="{ink}" stroke-opacity=".65" stroke-width="1.5"/><path d="M15 105h210M158 16v78m-120 38h47m17 0h25m27 0h45" fill="none" stroke="{ink}" stroke-opacity=".2"/><g transform="translate(181 44)" stroke="{ink}" fill="none" stroke-width="1.5"><rect width="28" height="28" rx="5"/><path d="M7 7h14v14H7zM5-4v4m9-4v4m9-4v4M5 28v4m9-4v4m9-4v4M-4 5h4m-4 9h4m-4 9h4m28-18h4m-4 9h4m-4 9h4"/></g><text x="24" y="40" fill="{ink}" font-family="Arial,sans-serif" font-size="10" letter-spacing="2">SOUVENIR / DEMO</text><text x="22" y="83" fill="#f1f1e8" font-family="Arial,sans-serif" font-weight="700" font-size="36" letter-spacing="-1">{symbol}</text><text x="24" y="124" fill="{ink}" font-family="Arial,sans-serif" font-size="11">NOT A SHARE. NO CASH VALUE.</text><text x="24" y="143" fill="#abc1cb" font-family="Arial,sans-serif" font-size="9">CTRL / WHALE AQUARIUM</text>',f'{symbol} fictional demo souvenir — not actual stock or security')
print('Created 4 original VFX SVGs and 3 clearly labeled demo souvenir SVGs.')
def sound(name,duration,fn,gain=.28):
 rate=22050;count=int(duration*rate);values=[fn(i/rate)*min(1,i/(rate*.02),(count-1-i)/(rate*.12)) for i in range(count)];peak=max(max(abs(v) for v in values),1e-9)
 p=ROOT/'audio'/f'{name}.wav'
 with wave.open(str(p),'wb') as w:
  w.setnchannels(1);w.setsampwidth(2);w.setframerate(rate);w.writeframes(b''.join(struct.pack('<h',int(v/peak*gain*32767)) for v in values))
sound('creature-pop',.52,lambda t:math.sin(math.tau*(420*t+800*t*t))*math.exp(-10*t)+.25*math.sin(math.tau*83*t)*math.exp(-7*t))
sound('treasure-open',1.25,lambda t:sum(math.sin(math.tau*f*t)*math.exp(-4*max(0,t-i*.14))*(t>=i*.14) for i,f in enumerate([392,523.25,659.25,783.99,1046.5])))
sound('black-hole',4.2,lambda t:(math.sin(math.tau*(100*t-8*t*t))+.4*math.sin(math.tau*(158*t-12*t*t))+.18*math.sin(math.tau*13*t)*math.sin(math.tau*547*t))*math.sin(math.pi*t/4.2)**.7,.22)
print('Created 3 original synthesized reveal/black-hole WAV sounds.')
